/* assets/reading-protection.js */
(() => {
  'use strict';
  if(window.PortfolioReading)return;
  const rawFile=/\.(?:pdf|docx?|zip)(?:[?#]|$)/i;
  const element=node=>node?.nodeType===1?node:node?.parentElement;
  const contact=node=>element(node)?.closest('#contact [data-copy-contact]');
  function selectedContact() {
    const selection=window.getSelection();
    if(!selection?.rangeCount||selection.isCollapsed)return false;
    const allowed=contact(selection.anchorNode);
    return !!allowed&&allowed===contact(selection.focusNode)&&Array.from({length:selection.rangeCount},(_,i)=>selection.getRangeAt(i)).every(r=>allowed.contains(r.startContainer)&&allowed.contains(r.endContainer));
  }
  function refresh() {
    document.querySelectorAll('a[href]').forEach(a=>{
      const href=a.getAttribute('href')||'';
      if(rawFile.test(href)||a.hasAttribute('download'))a.remove();
    });
    document.querySelectorAll('.actions button[onclick*="print"]').forEach(b=>b.remove());
    document.querySelectorAll('video').forEach(v=>v.setAttribute('controlslist','nodownload'));
  }
  ['copy','cut'].forEach(name=>document.addEventListener(name,event=>{if(!selectedContact())event.preventDefault();},true));
  document.addEventListener('contextmenu',event=>{if(!contact(event.target))event.preventDefault();},true);
  document.addEventListener('dragstart',event=>{if(!contact(event.target))event.preventDefault();},true);
  document.addEventListener('selectstart',event=>{
    if(contact(event.target))return;
    if(document.body.classList.contains('text-editing')&&element(event.target)?.closest('[contenteditable]'))return;
    event.preventDefault();
  },true);
  document.addEventListener('keydown',event=>{
    if(!(event.ctrlKey||event.metaKey))return;
    const key=event.key.toLowerCase();
    if(key==='s'||key==='p'){event.preventDefault();return;}
    if(key==='a'){
      const allowed=contact(event.target);
      if(allowed){event.preventDefault();const range=document.createRange();range.selectNodeContents(allowed);const s=window.getSelection();s.removeAllRanges();s.addRange(range);return;}
      if(document.body.classList.contains('text-editing')&&element(event.target)?.closest('[contenteditable]'))return;
      event.preventDefault();
    }
  },true);
  document.addEventListener('click',async event=>{
    if(!element(event.target)?.closest('#copy-phone'))return;
    const value=document.querySelector('#contact [data-copy-contact="phone"]')?.textContent||'';
    const phone=value.match(/(?:\+?86[- ]?)?1[3-9]\d{9}/)?.[0];
    if(!phone)return;
    try{await navigator.clipboard.writeText(phone);document.getElementById('copy-status').textContent='手机号已复制';}
    catch{document.getElementById('copy-status').textContent='可选中手机号复制。';}
  });
  window.PortfolioReading={refresh};
  const init=()=>{refresh();new MutationObserver(refresh).observe(document.body,{childList:true,subtree:true});};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

;
/* assets/image-preview.js */
(() => {
  'use strict';
  const detail = document.getElementById('project-dialog');
  if (!detail) return;
  const imageFile = /\.(?:avif|gif|jpe?g|png|svg|webp)(?:[?#]|$)/i;
  const preview = document.createElement('dialog');
  preview.id = 'image-preview';
  preview.setAttribute('aria-label', '图片预览');
  preview.innerHTML = '<div class="image-preview-toolbar"><button type="button" autofocus>关闭预览</button></div><figure><img alt="" draggable="false"><figcaption></figcaption></figure>';
  document.body.append(preview);
  const image = preview.querySelector('img');
  const caption = preview.querySelector('figcaption');
  let returnFocus;

  function prepare() {
    detail.querySelectorAll('a[href]').forEach(link => {
      if (!imageFile.test(link.getAttribute('href'))) return;
      link.removeAttribute('target');
      link.setAttribute('aria-haspopup', 'dialog');
      link.dataset.imagePreview = 'true';
      const photo = link.querySelector('img');
      link.setAttribute('aria-label', '预览' + (photo?.alt || link.textContent.trim() || '图片'));
    });
    detail.querySelectorAll('img').forEach(photo => {
      photo.draggable = false;
      if (photo.closest('a')) return;
      photo.tabIndex = 0;
      photo.setAttribute('role', 'button');
      photo.setAttribute('aria-haspopup', 'dialog');
      photo.setAttribute('aria-label', '预览' + (photo.alt || '图片'));
    });
  }

  function open(target) {
    const link = target.closest('a[data-image-preview]');
    const photo = link?.querySelector('img') || target.closest('img');
    const src = photo?.dataset.previewSrc || window.PortfolioMedia?.source(link?.getAttribute('href')) || link?.getAttribute('href') || photo?.currentSrc || photo?.src;
    if (!src || !detail.open) return;
    returnFocus = link || photo;
    image.src = photo?.currentSrc || photo?.src || src;
    if(image.src!==new URL(src,document.baseURI).href){
      const large=new Image();large.onload=()=>{if(preview.open&&returnFocus===(link||photo))image.src=src;};large.src=src;
    }
    image.alt = photo?.alt || link?.textContent.trim() || '作品图片';
    caption.textContent = returnFocus.closest('figure')?.querySelector('figcaption')?.textContent.trim() || image.alt;
    preview.showModal();
  }

  detail.addEventListener('click', event => {
    if (event.defaultPrevented || event.target.closest('[contenteditable="true"]')) return;
    const target = event.target.closest('a[data-image-preview], img');
    if (!target) return;
    event.preventDefault();
    open(target);
  });
  detail.addEventListener('keydown', event => {
    if (!event.target.matches('img[role="button"]') || !['Enter', ' '].includes(event.key)) return;
    event.preventDefault();
    open(event.target);
  });
  preview.querySelector('button').addEventListener('click', () => preview.close());
  preview.addEventListener('click', event => {
    if (event.target !== preview) return;
    const rect = preview.getBoundingClientRect();
    if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) preview.close();
  });
  preview.addEventListener('close', () => {
    image.removeAttribute('src');
    if (detail.open && returnFocus?.isConnected) returnFocus.focus({preventScroll: true});
  });
  detail.addEventListener('close', () => { if (preview.open) preview.close(); });
  document.addEventListener('portfolio:dialog-open', prepare);
  new MutationObserver(prepare).observe(detail, {childList: true, subtree: true});
  prepare();
})();

